### thorchain.ts (new file)
The Solana Tx type has `instructions: Array<{ accounts, data: string, programId: string, innerInstructions }>`. data field is base58-encoded.

```typescript
import bs58 from 'bs58'
import * as thorchain from '../../parser/thormaya'
import type { Tx } from '../types'
import type { SubParser, TxSpecific } from '../../parser'

const MEMO_PROGRAM_ID = 'MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr'

export class Parser implements SubParser<Tx> {
  private readonly parser: thorchain.Parser

  constructor(args: { midgardUrl: string }) {
    this.parser = new thorchain.Parser({ midgardUrl: args.midgardUrl })
  }

  async parse(tx: Tx): Promise<TxSpecific | undefined> {
    const memoInstruction = tx.instructions.find(i => i.programId === MEMO_PROGRAM_ID)
    if (\!memoInstruction) return

    const memo = Buffer.from(bs58.decode(memoInstruction.data)).toString('utf8')
    if (\!memo) return

    return await this.parser.parse(memo, tx.txid)
  }
}
```

